import type { RouteModule } from "@kasperrt/smolter/preact";
import { presentRoute } from "./presentation";
export const viewTransition: NonNullable<RouteModule["viewTransition"]> =
  (commit, previous, next) => presentRoute(commit, previous, next);
// React: use the equivalent @kasperrt/smolter/react type import.

export const viewTransition: NonNullable<RouteModule["viewTransition"]> =
  async (commit, previous, next) => {
    if (!next.leaving || !document.startViewTransition) return commit();
    const transition = document.startViewTransition(showDepartureState);
    await transition.finished;
    commit();
  };

// Leaving page
export const viewTransition: NonNullable<RouteModule["viewTransition"]> =
  (commit, previous, next) => {
    if (!next.leaving) return commit();
    commit({ crossDocument: ["handoff"] });
  };

/* Destination stylesheet, loaded before first paint */
@view-transition { navigation: auto; types: handoff; }
.loading-indicator { view-transition-name: loading; }
